#!/usr/bin/env php
<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){fwrite(STDERR,"CLI only.\n");exit(1);} $root=realpath(dirname(__DIR__))?:dirname(__DIR__);require_once $root.'/bootstrap.php';
use UnrealDb\Catalog\Infrastructure\Metadata\CatalogUnrealIdentityHash;
use UnrealDb\Catalog\Infrastructure\Metadata\Uedb5GameDependencyPassService;
use UnrealDb\Catalog\Infrastructure\Metadata\Uedb5SqlProjectionContract;
use UnrealDb\Catalog\Infrastructure\Persistence\PdoClassicSourceIdentityImpactQuery;
const OLD_POLICIES=['uedb5-dependency-pass-v1','uedb5-dependency-pass-v2'];
$o=getopt('',['game-id::','apply','rebuild-impacted','limit::']);$gid=max(0,(int)($o['game-id']??0));$apply=isset($o['apply']);$rebuild=isset($o['rebuild-impacted']);$limit=max(1,min(100000,(int)($o['limit']??1000)));if($rebuild&&!$apply){fwrite(STDERR,"--rebuild-impacted requires --apply.\n");exit(1);}
$app=catalog_bootstrap();$db=$app->db;$new=Uedb5GameDependencyPassService::DEPENDENCY_POLICY;if($new!=='uedb5-dependency-pass-v3')throw new RuntimeException('Source-identity transition requires dependency policy v3.');
$tables=['ue_uedb5_migration_status','ue_uedb5_files','ue_uedb5_provider_keys','ue_uedb5_dependency_edges','ue_uedb5_dependency_packages','ue_dependency_links','ue_terms','ue_name_lookup','ue_file_package_aliases','ue_games','ue_game_profiles'];$check=$db->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');foreach($tables as$t){$check->execute([$t]);if((int)$check->fetchColumn()!==1){echo json_encode(['ok'=>false,'missing_table'=>$t,'error'=>'Run catalog/bin/migrate.php migrate before the v3 source-identity transition.']),PHP_EOL;exit(1);}}
$q=new PdoClassicSourceIdentityImpactQuery($db);$current=$q->currentOldPolicyFiles($gid);$impact=$q->run($gid,array_map(static fn(array$r):int=>(int)$r['file_id'],$current));$reasons=(array)$impact['reasons_by_file'];$impacted=[];$unaffected=[];
foreach($current as$r){$fid=(int)$r['file_id'];$policy=(string)$r['dependency_policy'];$why=array_keys((array)($reasons[$fid]??[]));$identityWhy=array_values(array_filter($why,static fn(string$x):bool=>$x!=='provider_environment_ambiguity'));$needs=$policy==='uedb5-dependency-pass-v1'?($why!==[]):($identityWhy!==[]);$row=['file_id'=>$fid,'game_id'=>(int)$r['game_id'],'engine_key'=>(string)$r['engine_key'],'old_policy'=>$policy,'reasons'=>$why];if($needs)$impacted[]=$row;else$unaffected[]=$row;}
$where=$gid>0?' AND s.game_id=?':'';$args=array_merge(OLD_POLICIES,$gid>0?[$gid]:[]);$staleSql='SELECT COUNT(*) FROM ue_uedb5_migration_status s JOIN ue_uedb5_files v ON v.file_id=s.file_id AND v.game_id=s.game_id JOIN ue_files f ON f.id=s.file_id AND f.game_id=s.game_id WHERE f.scan_status="verified" AND s.dependency_policy IN (?,?) AND (s.dependency_payload_sha256 IS NULL OR s.dependency_payload_sha256<>v.payload_sha256)'.$where;$stale=$db->prepare($staleSql);$stale->execute($args);$staleCount=(int)$stale->fetchColumn();
$pre=['old_policies'=>OLD_POLICIES,'new_policy'=>$new,'game_id'=>$gid?:null,'current_old_policy_count'=>count($current),'unaffected_rollforward_count'=>count($unaffected),'impacted_rebuild_count'=>count($impacted),'stale_old_payload_count'=>$staleCount,'impact_reason_counts'=>$impact['reason_counts'],'impacted_file_ids_by_game'=>[]];foreach($impacted as$r)$pre['impacted_file_ids_by_game'][$r['game_id']][]=$r['file_id'];
if(!$apply){echo json_encode(['ok'=>true,'apply'=>false,'read_only'=>true,'preflight'=>$pre],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),PHP_EOL;exit(0);}

// Re-key only UE1/UE2/UE3 staged provider accelerators. UE4/UE5 stay on kind 1 until Section 2B.
$scope=$gid>0?' AND v.game_id='.(int)$gid:'';$select=$db->query('SELECT v.file_id,v.package_name FROM ue_uedb5_files v JOIN ue_games g ON g.id=v.game_id LEFT JOIN ue_game_profiles gp ON gp.id=g.profile_id AND gp.is_active=1 WHERE v.package_key_kind='.Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_NAME.' AND UPPER(COALESCE(gp.engine_key,"")) IN ("UE1","UE2","UE3")'.$scope);$exactRegistrations=$select->fetchAll(PDO::FETCH_ASSOC)?:[];
$db->beginTransaction();
try{
    $u=$db->prepare('UPDATE ue_uedb5_files SET package_key_kind=?,package_key=? WHERE file_id=? AND package_key_kind=?');foreach($exactRegistrations as$r)$u->execute([Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME,Uedb5SqlProjectionContract::classicPackageKeyBinary((string)$r['package_name'],Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME),(int)$r['file_id'],Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_NAME]);
    $db->exec('UPDATE ue_uedb5_provider_keys p JOIN ue_uedb5_files v ON v.file_id=p.file_id AND v.game_id=p.game_id SET p.package_key_kind=v.package_key_kind,p.package_key=v.package_key WHERE p.source_kind=1 AND v.package_key_kind='.Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME.($gid>0?' AND p.game_id='.(int)$gid:''));
    $aliasSql='SELECT p.source_id,a.package_name FROM ue_uedb5_provider_keys p JOIN ue_uedb5_files v ON v.file_id=p.file_id AND v.game_id=p.game_id JOIN ue_file_package_aliases a ON a.id=p.source_id AND a.file_id=p.file_id AND a.game_id=p.game_id WHERE p.source_kind=2 AND v.package_key_kind='.Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME.($gid>0?' AND p.game_id='.(int)$gid:'');$aliases=$db->query($aliasSql)->fetchAll(PDO::FETCH_ASSOC)?:[];$ua=$db->prepare('UPDATE ue_uedb5_provider_keys SET package_key_kind=?,package_key=? WHERE source_kind=2 AND source_id=?');foreach($aliases as$r)$ua->execute([Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME,Uedb5SqlProjectionContract::classicPackageKeyBinary((string)$r['package_name'],Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME),(int)$r['source_id']]);

    $exactUnaffected=array_values(array_filter($unaffected,static fn(array$r):bool=>in_array($r['engine_key'],['UE1','UE2','UE3'],true)));$selPkg=$db->prepare('SELECT file_id,game_id,package_key,required_package_name FROM ue_uedb5_dependency_packages WHERE file_id=? AND package_key_kind=?');$updEdge=$db->prepare('UPDATE ue_uedb5_dependency_edges SET required_package_key_kind=?,required_package_key=? WHERE file_id=? AND required_package_key_kind=? AND required_package_key=?');$updPkg=$db->prepare('UPDATE ue_uedb5_dependency_packages SET package_key_kind=?,package_key=? WHERE file_id=? AND package_key_kind=? AND package_key=?');foreach($exactUnaffected as$r){$fid=(int)$r['file_id'];$selPkg->execute([$fid,Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_NAME]);foreach($selPkg->fetchAll(PDO::FETCH_ASSOC)?:[] as$p){$old=(string)$p['package_key'];$newKey=Uedb5SqlProjectionContract::classicPackageKeyBinary((string)$p['required_package_name'],Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME);$updEdge->execute([Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME,$newKey,$fid,Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_NAME,$old]);$updPkg->execute([Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_FNAME,$newKey,$fid,Uedb5SqlProjectionContract::PACKAGE_KEY_CLASSIC_NAME,$old]);}}
    $us=$db->prepare('UPDATE ue_uedb5_migration_status SET dependency_policy=?,updated_at=UTC_TIMESTAMP() WHERE file_id=? AND dependency_policy IN (?,?)');foreach($unaffected as$r)$us->execute([$new,(int)$r['file_id'],OLD_POLICIES[0],OLD_POLICIES[1]]);
    $db->commit();
}catch(Throwable$e){if($db->inTransaction())$db->rollBack();throw$e;}

$rebuilt=[];$failed=[];if($rebuild){$svc=new Uedb5GameDependencyPassService($db,catalog_config());foreach(array_slice($impacted,0,$limit)as$r){try{$out=$svc->runFile((int)$r['game_id'],(int)$r['file_id'],true,true);$rebuilt[]=['game_id'=>(int)$r['game_id'],'file_id'=>(int)$r['file_id'],'reasons'=>$r['reasons'],'dependency_count'=>(int)($out['result']['dependency_count']??0)];}catch(Throwable$e){$failed[]=['game_id'=>(int)$r['game_id'],'file_id'=>(int)$r['file_id'],'error'=>$e->getMessage()];}}}
$result=['ok'=>$failed===[],'apply'=>true,'preflight'=>$pre,'rekeyed_exact_classic_registrations'=>count($exactRegistrations),'rolled_forward_unaffected'=>count($unaffected),'rebuilt_impacted'=>$rebuilt,'failed_impacted'=>$failed,'remaining_impacted_not_rebuilt'=>max(0,count($impacted)-count($rebuilt)),'rebuild_limit'=>$rebuild?$limit:0];echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),PHP_EOL;exit($failed===[]?0:2);
